// Config - const, never changes
const COURSE_ID = "javascript";
const TOTAL_LESSONS = 10;
const XP_PER_LESSON = 50;
const COINS_PER_LESSON = 10;

// User data - object type, const reference but properties change
const user = {
  name: "Prince",
  xp: 120,
  coins: 30,
  completed: 2,
  isLoggedIn: true, // Boolean
  lastLesson: null // Null - no last lesson yet
};

// Lessons - array type, const reference but content managed
const lessons = [
  { id: 1, title: "Introduction to JavaScript", status: "completed", xp: 100 },
  { id: 2, title: "Variables and Data Types", status: "completed", xp: 100 },
  { id: 3, title: "Operators and Expressions", status: "current", xp: 0 },
  { id: 4, title: "Conditions", status: "locked", xp: 0 },
];

// Function with type safety like your dashboard
function getSafeXP(data) {
  // Your dashboard pattern: Number(data.xp ?? data.profile?.xp ?? 0)
  return Number(data.xp ?? data.profile?.xp ?? 0);
}

function calculateProgress(completed, total) {
  // Your dashboard safety: Math.min, Math.max, Number() || 0
  completed = Math.min(total, Math.max(0, Number(completed) || 0));
  let percent = Math.round((completed / total) * 100);
  let text = `${completed} / ${total} completed`; // Template literal
  return { completed, percent, text };
}

function getLessonStatus(lessonId, completed) {
  // Boolean logic like your dashboard
  let isCompleted = lessonId <= completed;
  let isCurrent = lessonId === completed + 1;
  let isLocked = lessonId > completed + 1;

  if (isCompleted) return "completed";
  if (isCurrent) return "current";
  return "locked";
}

// Simulate completing lesson
function completeLesson(lessonId) {
  console.log(`\n--- Attempting Lesson ${lessonId} ---`);

  let status = getLessonStatus(lessonId, user.completed);
  console.log(`Status: ${status} (Completed: ${user.completed})`);

  if (status === "locked") {
    console.warn(`🔒 Locked! Complete lesson ${user.completed + 1} first.`);
    return;
  }

  if (status === "completed") {
    console.log(`✅ Already completed - reviewing ${lessons[lessonId-1].title}`);
    return;
  }

  // Complete current lesson
  user.completed += 1;
  user.xp += XP_PER_LESSON;
  user.coins += COINS_PER_LESSON;
  user.lastLesson = lessonId;

  // Update lesson status in array
  lessons[lessonId-1].status = "completed";
  lessons[lessonId-1].xp = XP_PER_LESSON;
  if (lessons[lessonId]) {
    lessons[lessonId].status = "current";
  }

  let progress = calculateProgress(user.completed, TOTAL_LESSONS);
  let safeXP = getSafeXP(user);

  console.log(`🎉 Completed!`);
  console.log(`💰 XP: ${safeXP} (+${XP_PER_LESSON}), Coins: ${user.coins}`);
  console.log(`📊 ${progress.text} - ${progress.percent}%`);
  console.log(`📚 Last lesson: ${user.lastLesson}`);
}

